import manifest from "@/data/photo-manifest.json";

type Entry = { width: number; height: number; widths: number[] };
const entries = manifest as Record<string, Entry>;

/**
 * Intrinsic size and WebP srcset for a supplied photo, e.g. "/photos/kg2.jpg".
 * The derivatives live in /photos/opt and are generated by `npm run images`.
 */
export function photoInfo(src: string) {
  const file = src.split("/").pop() ?? "";
  const entry = entries[file];
  if (!entry) return { width: undefined, height: undefined, srcSet: undefined, smallest: undefined };
  const base = file.replace(/\.[^.]+$/, "");
  const url = (w: number) => `/photos/opt/${base}-${w}.webp`;
  return {
    width: entry.width,
    height: entry.height,
    srcSet: entry.widths.map((w) => `${url(w)} ${w}w`).join(", "),
    smallest: url(entry.widths[0]),
  };
}
